+//! Apps do bench guiados por variaveis.
+//!
+//! `products/<p>/apps.json` referencia `${NOME_REPO}` / `${NOME_REF}`; os valores ficam em
+//! `products/<p>/build.env`. O `common/build-image.sh` renderiza o JSON antes do build.
+use crate::ops_core::envfile::EnvFile;
+use serde_json::{json, Value};
+use std::fs;
+use std::path::Path;
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct AppEntry {
+    /// Nome curto (ex.: lms, trivia_sync).
+    pub name: String,
+    /// Nomes das variaveis em build.env (None = entrada literal antiga).
+    pub repo_var: Option<String>,
+    pub ref_var: Option<String>,
+    /// Valores ja resolvidos ("" se a variavel falta ou esta vazia).
+    pub repo: String,
+    pub reference: String,
+    /// Problema legivel, se houver (variavel ausente/vazia, placeholder...).
+    pub problem: Option<String>,
+}
+
+pub fn var_names(name: &str) -> (String, String) {
+    let up = name.to_ascii_uppercase();
+    (format!("{up}_REPO"), format!("{up}_REF"))
+}
+
+pub fn validate_inputs(name: &str, repo: &str, reference: &str) -> Result<(), String> {
+    let ok_name = name.len() >= 2
+        && name.len() <= 32
+        && name.chars().next().is_some_and(|c| c.is_ascii_lowercase())
+        && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
+    if !ok_name {
+        return Err("Nome: use 2-32 caracteres [a-z0-9_], começando por letra (ex.: lms, trivia_sync).".into());
+    }
+    let bad = |s: &str| s.chars().any(|c| c.is_whitespace() || matches!(c, '"' | '\\' | '$' | '<' | '>' | '`'));
+    if repo.is_empty() {
+        return Err("Repositório: informe a URL Git.".into());
+    }
+    if !(repo.starts_with("https://") || repo.starts_with("ssh://") || repo.starts_with("git@")) || bad(repo) {
+        return Err("Repositório: use https://..., ssh://... ou git@... (sem espaços nem aspas).".into());
+    }
+    if reference.is_empty() {
+        return Err("Referência: informe uma tag ou commit (ex.: v16.1.0).".into());
+    }
+    if bad(reference) {
+        return Err("Referência: sem espaços, aspas ou $ < >.".into());
+    }
+    Ok(())
+}
+
+pub fn is_movable_ref(r: &str) -> bool {
+    r.starts_with("version-") || matches!(r, "main" | "master" | "develop")
+}
+
+fn valid_var(v: &str) -> bool {
+    let mut c = v.chars();
+    matches!(c.next(), Some(ch) if ch.is_ascii_uppercase() || ch == '_')
+        && c.all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_')
+}
+
+/// `${VAR}` inteiro -> Some("VAR").
+fn whole_var(s: &str) -> Option<&str> {
+    let inner = s.strip_prefix("${")?.strip_suffix('}')?;
+    valid_var(inner).then_some(inner)
+}
+
+/// Substitui todos os `${VAR}` usando build.env. Variavel ausente -> Err.
+pub fn resolve(s: &str, env: &EnvFile) -> Result<String, String> {
+    let mut out = String::new();
+    let mut rest = s;
+    while let Some(i) = rest.find("${") {
+        out.push_str(&rest[..i]);
+        let after = &rest[i + 2..];
+        let Some(j) = after.find('}') else {
+            return Err(format!("referência ${{ sem fechar em {s:?}"));
+        };
+        let var = &after[..j];
+        if !valid_var(var) {
+            return Err(format!("nome de variável inválido: {var:?}"));
+        }
+        match env.get(var) {
+            Some(v) => out.push_str(v),
+            None => return Err(format!("variável {var} ausente em build.env")),
+        }
+        rest = &after[j + 1..];
+    }
+    out.push_str(rest);
+    Ok(out)
+}
+
+fn load_env(dir: &Path) -> Result<EnvFile, String> {
+    match fs::read_to_string(dir.join("build.env")) {
+        Ok(t) => Ok(EnvFile::parse(&t)),
+        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(EnvFile::default()),
+        Err(e) => Err(format!("falha ao ler build.env: {e}")),
+    }
+}
+
+fn load_array(dir: &Path) -> Result<Vec<Value>, String> {
+    let path = dir.join("apps.json");
+    let text = match fs::read_to_string(&path) {
+        Ok(t) => t,
+        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(vec![]),
+        Err(e) => return Err(format!("falha ao ler {}: {e}", path.display())),
+    };
+    match serde_json::from_str::<Value>(&text) {
+        Ok(Value::Array(a)) => Ok(a),
+        Ok(_) => Err(format!("{}: esperado uma lista", path.display())),
+        Err(e) => Err(format!("{} inválido: {e}", path.display())),
+    }
+}
+
+pub fn derive_name(url: &str) -> String {
+    sanitize_name(url)
+}
+
+fn sanitize_name(s: &str) -> String {
+    let n: String = s
+        .trim_end_matches(".git")
+        .rsplit('/')
+        .next()
+        .unwrap_or("")
+        .chars()
+        .map(|c| if c.is_ascii_alphanumeric() { c.to_ascii_lowercase() } else { '_' })
+        .collect();
+    if n.is_empty() { "app".into() } else { n }
+}
+
+pub fn load(dir: &Path) -> Result<Vec<AppEntry>, String> {
+    let env = load_env(dir)?;
+    let arr = load_array(dir)?;
+    let mut out = Vec::new();
+    for (i, a) in arr.iter().enumerate() {
+        let raw_url = a.get("url").and_then(|x| x.as_str()).unwrap_or("");
+        let raw_ref = a.get("branch").and_then(|x| x.as_str()).unwrap_or("");
+        let repo_var = whole_var(raw_url).map(String::from);
+        let ref_var = whole_var(raw_ref).map(String::from);
+        let mut problems: Vec<String> = Vec::new();
+        let mut value = |raw: &str| match resolve(raw, &env) {
+            Ok(v) => v,
+            Err(e) => {
+                problems.push(e);
+                String::new()
+            }
+        };
+        let repo = value(raw_url);
+        let reference = value(raw_ref);
+        // variaveis que existem mas estao vazias (ex.: LMS_REF=)
+        let mut empty_vars: Vec<&str> = Vec::new();
+        if let (Some(v), true) = (&repo_var, repo.is_empty() && problems.is_empty()) {
+            empty_vars.push(v);
+        }
+        if let (Some(v), true) = (&ref_var, reference.is_empty() && !problems.iter().any(|p| p.contains(ref_var.as_deref().unwrap_or("")))) {
+            empty_vars.push(v);
+        }
+        if !empty_vars.is_empty() {
+            problems.push(format!("vazias em build.env: {}", empty_vars.join(", ")));
+        }
+        if repo_var.is_none() && repo.is_empty() {
+            problems.push("repositório vazio".into());
+        }
+        for s in [&repo, &reference] {
+            if s.contains('<') || s.contains('>') {
+                problems.push(format!("placeholder {s}"));
+            }
+        }
+        let name = repo_var
+            .as_deref()
+            .and_then(|v| v.strip_suffix("_REPO"))
+            .map(|n| n.to_ascii_lowercase())
+            .unwrap_or_else(|| {
+                if repo.is_empty() { format!("app{}", i + 1) } else { sanitize_name(&repo) }
+            });
+        out.push(AppEntry {
+            name,
+            repo_var,
+            ref_var,
+            repo,
+            reference,
+            problem: if problems.is_empty() { None } else { Some(problems.join("; ")) },
+        });
+    }
+    Ok(out)
+}
+
+/// Escrita atomica com backup (ultimos 5) do apps.json.
+fn save_array(dir: &Path, arr: &[Value]) -> Result<(), String> {
+    let path = dir.join("apps.json");
+    let out = serde_json::to_string_pretty(arr).map_err(|e| format!("falha ao preparar apps.json: {e}"))?;
+    if path.exists() {
+        let ts = std::time::SystemTime::now()
+            .duration_since(std::time::UNIX_EPOCH)
+            .map(|d| d.as_secs())
+            .unwrap_or(0);
+        let _ = fs::copy(&path, dir.join(format!("apps.json.bak-{ts}")));
+        let mut baks: Vec<String> = fs::read_dir(dir)
+            .map(|rd| {
+                rd.filter_map(|e| e.ok())
+                    .filter_map(|e| e.file_name().into_string().ok())
+                    .filter(|n| n.starts_with("apps.json.bak-"))
+                    .collect()
+            })
+            .unwrap_or_default();
+        baks.sort();
+        while baks.len() > 5 {
+            let _ = fs::remove_file(dir.join(baks.remove(0)));
+        }
+    }
+    let tmp = dir.join("apps.json.tmp");
+    fs::write(&tmp, out + "\n").map_err(|e| format!("falha ao salvar {}: {e}", tmp.display()))?;
+    fs::rename(&tmp, &path).map_err(|e| format!("falha ao salvar {}: {e}", path.display()))
+}
+
+/// Cria ou atualiza um app: grava NOME_REPO/NOME_REF em build.env e garante a entrada no apps.json.
+/// `allow_existing=false` recusa nome ja existente (modo "adicionar").
+pub fn upsert(dir: &Path, name: &str, repo: &str, reference: &str, allow_existing: bool) -> Result<(), String> {
+    validate_inputs(name, repo, reference)?;
+    let (repo_var, ref_var) = var_names(name);
+    let mut arr = load_array(dir)?;
+    let (rv, fv) = (format!("${{{repo_var}}}"), format!("${{{ref_var}}}"));
+    let exists = arr.iter().any(|a| a.get("url").and_then(|x| x.as_str()) == Some(rv.as_str()));
+    if exists && !allow_existing {
+        return Err(format!("Já existe um app chamado '{name}'. Selecione-o e use Enter para editar."));
+    }
+    let mut env = load_env(dir)?;
+    env.set(&repo_var, repo)?;
+    env.set(&ref_var, reference)?;
+    env.save(&dir.join("build.env"))?;
+    if !exists {
+        arr.push(json!({"url": rv, "branch": fv}));
+        save_array(dir, &arr)?;
+    }
+    Ok(())
+}
+
+/// Remove a entrada `index` do apps.json e, se ninguem mais usa, as variaveis dela em build.env.
+pub fn remove(dir: &Path, index: usize) -> Result<String, String> {
+    let mut arr = load_array(dir)?;
+    if index >= arr.len() {
+        return Err("nenhum app selecionado".into());
+    }
+    let gone = arr.remove(index);
+    let url = gone.get("url").and_then(|x| x.as_str()).unwrap_or("");
+    let br = gone.get("branch").and_then(|x| x.as_str()).unwrap_or("");
+    let label = whole_var(url)
+        .and_then(|v| v.strip_suffix("_REPO"))
+        .map(|n| n.to_ascii_lowercase())
+        .unwrap_or_else(|| sanitize_name(url));
+    save_array(dir, &arr)?;
+    let used = |var: &str| {
+        arr.iter().any(|a| {
+            ["url", "branch"]
+                .iter()
+                .any(|k| a.get(*k).and_then(|x| x.as_str()).is_some_and(|s| s.contains(&format!("${{{var}}}"))))
+        })
+    };
+    let mut env = load_env(dir)?;
+    let mut changed = false;
+    for v in [whole_var(url), whole_var(br)].into_iter().flatten() {
+        if !used(v) {
+            changed |= env.remove(v);
+        }
+    }
+    if changed {
+        env.save(&dir.join("build.env"))?;
+    }
+    Ok(label)
+}
